decode_matrix <- function(s,nr,nc) { b <- strtoi(substring(s,seq(1,nchar(s),2),seq(2,nchar(s),2)),16L); bits <- as.integer(rawToBits(as.raw(b))); matrix(bits[seq_len(nr*nc)],nr,nc) }
